306	     * does not catch). The names of all offending fields are collected so the caller receives a
307	     * 400 response whose {@code errors} array lists each one.
308	     */
309	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
310	        List<String> missingFields = new ArrayList<>();
311	        if (isBlank(ownerFieldsDto.getFirstName())) {
312	            missingFields.add("firstName");
313	        }
314	        if (isBlank(ownerFieldsDto.getLastName())) {
315	            missingFields.add("lastName");
316	        }
317	        if (isBlank(ownerFieldsDto.getAddress())) {
318	            missingFields.add("address");
319	        }
320	        if (isBlank(ownerFieldsDto.getCity())) {
321	            missingFields.add("city");
322	        }
323	        if (isBlank(ownerFieldsDto.getTelephone())) {
324	            missingFields.add("telephone");
325	        }
326	        if (!missingFields.isEmpty()) {
327	            throw new InvalidOwnerFieldsException(missingFields);
328	        }
329	    }
