335	    /**
336	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
337	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
338	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
339	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
340	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
341	     * means an address that is blank after normalization is rejected like a missing one.
342	     */
343	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
344	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
345	    }
346	
347	    /**
348	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
349	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
350	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
351	     * address is returned unchanged, making it safe to apply to stored values during comparison.
352	     */
353	    private static String canonicalAddress(String address) {
354	        if (address == null) {
355	            return null;
356	        }
357	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
358	        if (collapsed.isEmpty()) {
359	            return "";
360	        }
361	        String[] tokens = collapsed.split(" ");
362	        StringBuilder sb = new StringBuilder(collapsed.length());
363	        for (int i = 0; i < tokens.length; i++) {
364	            if (i > 0) {
365	                sb.append(' ');
366	            }
367	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
368	        }
369	        return sb.toString();
370	    }
