372	    /**
373	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
374	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
375	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
376	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
377	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
378	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
379	     * written back onto the request so it is what gets stored and returned. Any value that cannot
380	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
381	     * {@code telephone}.
382	     */
383	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
384	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
385	    }
386	
387	    /**
388	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
389	     * (400) naming {@code telephone} when it cannot form a valid number.
390	     */
391	    private static String toE164(String telephone) {
392	        if (telephone == null) {
393	            throw new InvalidOwnerFieldsException(List.of("telephone"));
394	        }
395	        boolean hasCountryCode = telephone.trim().startsWith("+");
396	        String digits = telephone.replaceAll("\\D", "");
397	        String countryCode;
398	        String national;
399	        if (hasCountryCode) {
400	            countryCode = matchCountryCode(digits);
401	            national = digits;
402	        } else {
403	            countryCode = "61";
404	            if (digits.startsWith("0")) {
405	                digits = digits.substring(1);
406	            }
407	            national = "61" + digits;
408	        }
409	        if (!national.matches("[0-9]{8,15}")) {
410	            throw new InvalidOwnerFieldsException(List.of("telephone"));
411	        }
412	        if (countryCode != null) {
413	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
414	            if (requiredLength != null
415	                && national.length() - countryCode.length() != requiredLength) {
416	                throw new InvalidOwnerFieldsException(List.of("telephone"));
417	            }
418	        }
419	        return "+" + national;
420	    }
421	
422	    /**
423	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
424	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
425	     * the number is not length-checked against a country.
426	     */
427	    private static String matchCountryCode(String digits) {
428	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
429	            .filter(digits::startsWith)
430	            .max(Comparator.comparingInt(String::length))
431	            .orElse(null);
432	    }
