434	    /**
435	     * Rejects creating an owner that duplicates an existing one, either as a household duplicate or
436	     * as an exact identity duplicate. The household is now keyed on the computed {@code householdId}
437	     * (a deterministic function of the normalized last name and postcode, see
438	     * {@link #computeHouseholdId}), so any existing owner already carrying the same {@code householdId}
439	     * belongs to the same household and makes the new owner a household duplicate. Independently, an
440	     * exact match on the derived {@code identityKey} - {@code normalizedTelephone + '|' + (email or
441	     * empty) + '|' + (householdId or empty)} - is also a duplicate; this still catches owners with no
442	     * postcode (and therefore no household) that share a telephone and email. Both checks are a 409.
443	     *
444	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block: a request that opts in
445	     * is allowed through even when it lands in an existing household, so it is created as a declared
446	     * household member rather than rejected. The incoming telephone and email have already been
447	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}; each existing owner's key
448	     * is derived the same way before comparison. A match results in a 409 response naming
449	     * {@code identityKey}.
450	     */
451	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId) {
452	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
453	            return;
454	        }
455	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
456	        for (Owner existing : this.clinicService.findAllOwners()) {
457	            boolean householdDuplicate = householdId != null && householdId.equals(existing.getHouseholdId());
458	            if (householdDuplicate || identityKey.equals(existingIdentityKey(existing))) {
459	                throw new DuplicateOwnerIdentityException(identityKey);
460	            }
461	        }
462	    }
463	
464	    /**
465	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
466	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
467	     * are expected to already be in their normalized (E.164, lower-cased) forms.
468	     */
469	    private static String identityKey(String telephone, String email, String householdId) {
470	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
471	    }
472	
473	    /**
474	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
475	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
476	     * the stored email is lower-cased, and the stored household id is used as-is.
477	     */
478	    private static String existingIdentityKey(Owner existing) {
479	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
480	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
481	        return identityKey(telephone, email, existing.getHouseholdId());
482	    }
483	
484	    private static String orEmpty(String value) {
485	        return value == null ? "" : value;
486	    }
487	
488	    /**
489	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
490	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
491	     */
492	    private static String normalizeExisting(String telephone) {
493	        try {
494	            return toE164(telephone);
495	        } catch (InvalidOwnerFieldsException ex) {
496	            return null;
497	        }
498	    }
