500	    /**
501	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
502	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
503	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
504	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
505	     */
506	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
507	        String city = ownerFieldsDto.getCity();
508	        int count = 0;
509	        for (Owner existing : this.clinicService.findAllOwners()) {
510	            if (city.equalsIgnoreCase(existing.getCity())) {
511	                count++;
512	            }
513	        }
514	        if (count >= MAX_OWNERS_PER_CITY) {
515	            throw new OwnerCityAtCapacityException(city);
516	        }
517	    }
