519	    /**
520	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
521	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
522	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
523	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
524	     */
525	    private void rejectDailyLimitReached(LocalDate registrationDate) {
526	        int count = 0;
527	        for (Owner existing : this.clinicService.findAllOwners()) {
528	            if (registrationDate.equals(existing.getRegistrationDate())) {
529	                count++;
530	            }
531	        }
532	        if (count >= MAX_OWNERS_PER_DAY) {
533	            throw new DailyOwnerLimitReachedException(registrationDate);
534	        }
535	    }
