537	    /**
538	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
539	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
540	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
541	     */
542	    private static String normalizeForComparison(String value) {
543	        if (value == null) {
544	            return "";
545	        }
546	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
547	    }
