549	    /**
550	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
551	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
552	     * written back onto the request so that is what gets stored and returned. A present but invalid
553	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
554	     */
555	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
556	        String email = ownerFieldsDto.getEmail();
557	        if (email == null) {
558	            return;
559	        }
560	        String trimmed = email.trim();
561	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
562	            throw new InvalidOwnerFieldsException(List.of("email"));
563	        }
564	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
