567	    /**
568	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
569	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
570	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
571	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
572	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
573	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
574	     * as-is so it is stored and returned.
575	     */
576	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
577	        String postcode = ownerFieldsDto.getPostcode();
578	        if (postcode == null) {
579	            return;
580	        }
581	        if (!postcode.matches("[0-9]{4}")) {
582	            throw new InvalidOwnerFieldsException(List.of("postcode"));
583	        }
584	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
585	        if (range != null) {
586	            int value = Integer.parseInt(postcode);
587	            if (value < range[0] || value > range[1]) {
588	                throw new InvalidOwnerFieldsException(List.of("postcode"));
589	            }
590	        }
591	    }
