593	    /**
594	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
595	     * day. When the caller supplies no value it defaults to the server's current date; a value
596	     * provided in the request is kept. A supplied value later than the server's current date is
597	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
598	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
599	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
600	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
601	     * every value derived from the registration date is based on.
602	     */
603	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
604	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
605	        if (effective == null) {
606	            effective = LocalDate.now();
607	        }
608	        else if (effective.isAfter(LocalDate.now())) {
609	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
610	        }
611	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
612	    }
