614	    /**
615	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
616	     * Monday; a weekday is returned unchanged.
617	     */
618	    private static LocalDate toBusinessDay(LocalDate date) {
619	        return switch (date.getDayOfWeek()) {
620	            case SATURDAY -> date.plusDays(2);
621	            case SUNDAY -> date.plusDays(1);
622	            default -> date;
623	        };
624	    }
