626	    /**
627	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
628	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
629	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
630	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
631	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
632	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
633	     * pure function of region, telephone and last name.
634	     */
635	    private void assignCustomerCode(Owner owner) {
636	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
637	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
638	        owner.setCustomerCode(region + "-" + hash8);
639	    }
