643	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
644	     * {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Assigned after
645	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
646	     * inputs are present.
647	     */
648	    private void assignMembershipNumber(Owner owner) {
649	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
650	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
651	    }
