653	    /**
654	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
655	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
656	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
657	     */
658	    private void assignNamesakeCount(Owner owner) {
659	        String firstName = owner.getFirstName();
660	        String lastName = owner.getLastName();
661	        int count = 0;
662	        for (Owner existing : this.clinicService.findAllOwners()) {
663	            if (firstName.equalsIgnoreCase(existing.getFirstName())
664	                && lastName.equalsIgnoreCase(existing.getLastName())) {
665	                count++;
666	            }
667	        }
668	        owner.setNamesakeCount(count);
