671	    /**
672	     * Assigns the new owner's {@code membershipLevel} on create: a number from 1 to 3 starting at
673	     * 1, plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3.
674	     * Level 4 is reserved for tenure. Runs after {@link #assignNamesakeCount} so that count is
675	     * settled.
676	     */
677	    private void assignMembershipLevel(Owner owner) {
678	        int level = 1;
679	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
680	            level++;
681	        }
682	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
683	            level++;
684	        }
685	        owner.setMembershipLevel(Math.min(level, 3));
686	    }
