706	    /**
707	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
708	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
709	     * possible duplicate when an existing owner shares its {@code lastName} (compared
710	     * case-insensitively) and its {@code postcode} (a present, exact match) while carrying a different
711	     * {@code telephone}. When such an owner exists, {@code possibleDuplicate} is set to {@code true}
712	     * and {@code possibleDuplicateOf} to that owner's id (the lowest id when several match); otherwise
713	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is left {@code null}.
714	     * Computed before the new owner is persisted, so it considers only the pre-existing owners.
715	     *
716	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
717	     * has deliberately opted into an existing household, so its shared last name and postcode are
718	     * expected rather than a suspected duplicate.
719	     */
720	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
721	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
722	            owner.setPossibleDuplicate(false);
723	            owner.setPossibleDuplicateOf(null);
724	            return;
725	        }
726	        String lastName = owner.getLastName();
727	        String postcode = owner.getPostcode();
728	        String telephone = owner.getTelephone();
729	        Integer matchId = null;
730	        if (postcode != null) {
731	            for (Owner existing : this.clinicService.findAllOwners()) {
732	                if (lastName.equalsIgnoreCase(existing.getLastName())
733	                    && postcode.equals(existing.getPostcode())
734	                    && !postcode.isBlank()
735	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
736	                    && existing.getId() != null
737	                    && (matchId == null || existing.getId() < matchId)) {
738	                    matchId = existing.getId();
739	                }
740	            }
741	        }
742	        owner.setPossibleDuplicate(matchId != null);
743	        owner.setPossibleDuplicateOf(matchId);
744	    }
745	
746	    /**
747	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
748	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
749	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
750	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
751	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
752	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
753	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
754	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
755	     * ({@link #assignHouseholdMembership}).
756	     */
757	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
758	        String postcode = ownerFieldsDto.getPostcode();
759	        if (postcode == null || postcode.isBlank()) {
760	            return null;
761	        }
762	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
763	        return shaHexUpper(lastName + "|" + postcode, 12);
764	    }
765	
766	    /**
767	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
768	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
769	     * every existing owner already carrying the same identifier. Runs after the owner's
770	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
771	     * Left {@code null} when the owner belongs to no household.
772	     */
773	    private void assignHouseholdMembership(Owner owner) {
774	        String householdId = owner.getHouseholdId();
775	        if (householdId == null || householdId.isBlank()) {
776	            owner.setHouseholdMemberCount(null);
777	            return;
778	        }
779	        int count = 1;
780	        for (Owner existing : this.clinicService.findAllOwners()) {
781	            if (householdId.equals(existing.getHouseholdId())) {
782	                count++;
783	            }
784	        }
785	        owner.setHouseholdMemberCount(count);
786	    }
787	
788	    /**
789	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
790	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
791	     * identifier, both stable functions of their inputs.
792	     */
793	    private static String shaHexUpper(String input, int length) {
794	        try {
795	            byte[] digest = MessageDigest.getInstance("SHA-256")
796	                .digest(input.getBytes(StandardCharsets.UTF_8));
797	            StringBuilder hex = new StringBuilder(digest.length * 2);
798	            for (byte b : digest) {
799	                hex.append(String.format("%02x", b));
800	            }
801	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
802	        } catch (NoSuchAlgorithmException ex) {
803	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
804	        }
805	    }
806	}
